violating:
import { Effect } from "effect"
import { Command, Flag } from "effect/unstable/cli"
import { ProductRepository } from "@workspace/catalog/ProductRepository"
import { SearchIndex } from "@workspace/search/SearchIndex"
import { buildReindexPlan } from "../../../../scripts/reindex-products/plan.ts"
import { formatReindexSummary } from "../../../../scripts/reindex-products/summary.ts"

export const reindexProducts = Command.make(
  "reindex-products",
  {
    dryRun: Flag.boolean("dry-run"),
    batchSize: Flag.integer("batch-size").pipe(Flag.withDefault(100))
  },
  ({ dryRun, batchSize }) =>
    Effect.gen(function*() {
      const products = yield* ProductRepository
      const index = yield* SearchIndex
      const records = yield* products.listPublished()
      const indexedIds = yield* index.listProductIds()
      const plan = buildReindexPlan(records, indexedIds, batchSize)

      yield* Effect.logInfo(`Prepared ${plan.batches.length} indexing batches`)

      if (dryRun) {
        yield* Effect.logInfo(formatReindexSummary(plan, "preview"))
        return
      }

      yield* Effect.forEach(
        plan.batches,
        (batch) => index.upsertProducts(batch),
        { concurrency: 4, discard: true }
      )
      yield* index.removeProducts(plan.staleIds)
      yield* Effect.logInfo(formatReindexSummary(plan, "completed"))
    })
)

